class Solution(object):
    def nearestExit(self, maze, entrance):
        """
        :type maze: List[List[str]]
        :type entrance: List[int]
        :rtype: int
        """
        rows = len(maze)-1
        cols = len(maze[0])-1

        def is_border(cordinates):

            if 0 in cordinates or rows == cordinates[0] or cols == cordinates[1]:
                return True
            return False

        neabours = [(0, -1), (-1, 0), (0, 1), (1, 0)]


        queue = deque([(entrance, 0)])
        visited = set([tuple(entrance)])

        while queue:
            current = queue.popleft()

            if is_border(current[0]) and current[0] != entrance:
                return current[1]

            for n in neabours:
                new_row, new_col = current[0][0] + n[0], current[0][1] + n[1]

                if 0 <= new_row <= rows and 0 <= new_col <= cols and maze[new_row][new_col] == "." and (new_row, new_col) not in visited:
                    queue.append(([new_row, new_col], current[1]+1))
                    visited.add((new_row, new_col))


        return -1

class Solution {
public:
    int nearestExit(vector<vector<char>>& maze, vector<int>& entrance) {
        int rows = int(maze.size()), cols = int(maze[0].size());
        vector<pair<int, int>> dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        // Mark the entrance as visited since its not a exit.
        int startRow = entrance[0], startCol = entrance[1];
        maze[startRow][startCol] = '+';

        // Start BFS from the entrance, and use a queue `queue` to store all 
        // the cells to be visited.
        queue<array<int, 3>> queue;
        queue.push({startRow, startCol, 0});

        while (!queue.empty()) {
            auto [currRow, currCol, currDistance] = queue.front();
            queue.pop();

            // For the current cell, check its four neighbor cells.
            for (auto dir : dirs) {
                int nextRow = currRow + dir.first, nextCol = currCol + dir.second;

                // If there exists an unvisited empty neighbor:
                if (0 <= nextRow && nextRow < rows && 0 <= nextCol && nextCol < cols \
                   && maze[nextRow][nextCol] == '.') {

                    // If this empty cell is an exit, return distance + 1.
                    if (nextRow == 0 || nextRow == rows - 1 || nextCol == 0 || nextCol == cols - 1)
                        return currDistance + 1;

                    // Otherwise, add this cell to 'queue' and mark it as visited.
                    maze[nextRow][nextCol] = '+';
                    queue.push({nextRow, nextCol, currDistance + 1});

                }
            }
        }

        // If we finish iterating without finding an exit, return -1.
        return -1;
    }
};

class Solution {
    public int nearestExit(char[][] maze, int[] entrance) {
        int rows = maze.length, cols = maze[0].length;
        int[][] dirs = new int[][]{{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        // Mark the entrance as visited since its not a exit.
        int startRow = entrance[0], startCol = entrance[1];
        maze[startRow][startCol] = '+';

        // Start BFS from the entrance, and use a queue `queue` to store all 
        // the cells to be visited.
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startRow, startCol, 0});

        while (!queue.isEmpty()) {
            int[] currState = queue.poll();
            int currRow = currState[0], currCol = currState[1], currDistance = currState[2];

            // For the current cell, check its four neighbor cells.
            for (int[] dir : dirs) {
                int nextRow = currRow + dir[0], nextCol = currCol + dir[1];

                // If there exists an unvisited empty neighbor:
                if (0 <= nextRow && nextRow < rows && 0 <= nextCol && nextCol < cols
                   && maze[nextRow][nextCol] == '.') {

                    // If this empty cell is an exit, return distance + 1.
                    if (nextRow == 0 || nextRow == rows - 1 || nextCol == 0 || nextCol == cols - 1)
                        return currDistance + 1;

                    // Otherwise, add this cell to 'queue' and mark it as visited.
                    maze[nextRow][nextCol] = '+';
                    queue.offer(new int[]{nextRow, nextCol, currDistance + 1});
                }  
            }
        }

        // If we finish iterating without finding an exit, return -1.
        return -1;
    }
}

